const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=JSON.parse(localStorage.getItem('consultas-v1')||'[]'),cfg=JSON.parse(localStorage.getItem('config-v1')||'{"mode":"demo","url":""}'),pending=[],running=false;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function persist(){if(cfg.mode==='demo')localStorage.setItem('consultas-v1',JSON.stringify(records));render()}
function render(){const q=$('#search').value.toLowerCase(),f=$('#filter').value;$('#total').textContent=records.length;$('#waiting').textContent=records.filter(r=>['Aguardando','Processando','Aguardando retorno'].includes(r.status)).length;$('#done').textContent=records.filter(r=>r.status==='Concluída').length;$('#errors').textContent=records.filter(r=>r.status==='Erro').length;$('.modeNotice').textContent=cfg.mode==='demo'?'Modo demonstração · Nenhum dado é enviado ao Digi+. Resultados simulados e histórico salvos apenas neste navegador.':'Modo API · Consultas enviadas à VPS configurada. A conclusão depende do serviço e do conector real.';$('#rows').innerHTML=records.filter(r=>(!f||r.status===f)&&`${r.nome} ${r.cpf}`.toLowerCase().includes(q)).map(r=>`<tr><td><b>${escapeHTML(r.nome)}</b><br><span class="muted">${escapeHTML(r.cpf)}</span></td><td><span class="pill ${r.status==='Concluída'?'ok':r.status==='Erro'?'err':r.status==='Processando'?'run':''}">${escapeHTML(r.status)}</span>${r.message?`<br><small title="${escapeHTML(r.message)}">${escapeHTML(r.message)}</small>`:''}</td><td>${r.saldo==null?'—':r.saldo.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</td><td>${r.parcelas??'—'}</td><td>${escapeHTML(r.source)}<br><span class="muted">${new Date(r.date).toLocaleString('pt-BR')}</span></td><td>${r.status==='Erro'?`<button data-retry="${r.id}">Tentar novamente</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhuma consulta por aqui.<br><small>Consulte um cliente ou importe sua primeira planilha.</small></td></tr>'}
const digits=s=>s.replace(/\D/g,'');function validate(r){r.nome=r.nome.trim();r.cpf=digits(r.cpf);r.telefone=digits(r.telefone);if(!r.nome||r.cpf.length!==11||!/^\d{10,13}$/.test(r.telefone))throw Error('Informe nome, CPF com 11 dígitos e telefone com DDD.');return r}
async function add(items){if(cfg.mode==='api'&&!sessionStorage.getItem('api-token'))return toast('Informe sua chave de acesso em Configurações.');for(const item of items)records.unshift({...item,id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),date:new Date().toISOString(),status:'Aguardando',source:cfg.mode==='demo'?'Demonstração':'API VPS',mode:cfg.mode,endpoint:cfg.url});persist();pump()}
async function pump(){if(running)return;running=true;try{for(const r of records.filter(r=>r.status==='Aguardando')){r.status='Processando';persist();try{if(r.mode==='demo'){await new Promise(ok=>setTimeout(ok,1000));r.saldo=4321.50;r.parcelas=72;r.message='Resultado fictício';r.status='Concluída'}else{const response=await fetch(r.endpoint+'/consultas',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+sessionStorage.getItem('api-token')},body:JSON.stringify({nome:r.nome,cpf:r.cpf,telefone:r.telefone}),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Erro na API');r.remoteId=data.id;r.status='Aguardando retorno';r.message='Recebida pela VPS';} }catch(e){r.status='Erro';r.message=e.name==='TimeoutError'?'Tempo de conexão excedido':e.message}persist()}}finally{running=false}}
async function poll(){for(const r of records.filter(r=>r.remoteId&&r.status==='Aguardando retorno')){try{const res=await fetch(r.endpoint+'/consultas/'+encodeURIComponent(r.remoteId),{headers:{Authorization:'Bearer '+sessionStorage.getItem('api-token')},signal:AbortSignal.timeout(10000)});if(!res.ok)continue;const d=await res.json();if(d.status==='concluida'){r.status='Concluída';r.saldo=d.saldo_liquidacao;r.parcelas=d.total_parcelas;r.message=d.message||'';r.date=d.consultado_em||r.date}else if(d.status==='erro'){r.status='Erro';r.message=d.error||'Falha na consulta'}persist()}catch{}}}setInterval(poll,5000);
$('#single').onsubmit=e=>{e.preventDefault();try{add([validate(Object.fromEntries(new FormData(e.target)))]);e.target.reset()}catch(e){toast(e.message)}};
function csvParse(text){const sep=text.split(/\r?\n/)[0].includes(';')?';':',';let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(value);value=''}else if(c==='\n'&&!quoted){row.push(value.replace(/\r$/,''));rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('CSV com aspas não fechadas.');if(value||row.length){row.push(value.replace(/\r$/,''));rows.push(row)}return rows.filter(r=>r.some(v=>v.trim()))}
$('#file').onchange=async e=>{pending=[];$('#import').disabled=true;try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Arquivo acima de 2 MB.');const rows=csvParse((await file.text()).replace(/^\uFEFF/,'')),headers=rows.shift().map(x=>x.trim().toLowerCase());if(!['nome','cpf','telefone'].every(h=>headers.includes(h)))throw Error('O arquivo deve conter nome, cpf e telefone.');if(rows.length>1000)throw Error('Envie até 1.000 registros por arquivo.');let errors=[];rows.forEach((row,i)=>{try{pending.push(validate(Object.fromEntries(headers.map((h,j)=>[h,row[j]||'']))))}catch{errors.push('Linha '+(i+2)+': dados incompletos ou inválidos')}});$('#preview').classList.remove('hide');$('#preview').textContent=`${pending.length} válidos · ${errors.length} inválidos\n`+errors.slice(0,10).join('\n');$('#import').disabled=!pending.length}catch(e){toast(e.message)}};
$('#import').onclick=()=>{add(pending);toast(pending.length+' registros adicionados.');pending=[];$('#file').value='';$('#import').disabled=true;$('#preview').classList.add('hide')};
function download(name,content){const u=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#sample').onclick=()=>download('modelo-consultas.csv','nome;cpf;telefone\nCLIENTE EXEMPLO;00000000000;11999999999\n');
$('#export').onclick=()=>{const safe=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';download('consultas.csv',[['nome','cpf','telefone','status','saldo','parcelas','origem','data','observacao'],...records.map(r=>[r.nome,r.cpf,r.telefone,r.status,r.saldo,r.parcelas,r.source,r.date,r.message])].map(r=>r.map(safe).join(';')).join('\r\n'))};
$('#demo').onclick=()=>{if(cfg.mode!=='demo')return toast('Selecione o modo demonstração nas configurações.');add([{nome:'Cliente exemplo A',cpf:'00000000000',telefone:'11999999999'}])};$('#clear').onclick=()=>{if(confirm('Apagar todo o histórico salvo neste navegador?')){records=[];persist()}};$('#rows').onclick=e=>{const id=e.target.dataset.retry;if(id){const r=records.find(r=>r.id===id);r.status='Aguardando';r.message='';delete r.remoteId;persist();pump()}};$('#search').oninput=render;$('#filter').onchange=render;
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$('#home').classList.toggle('hide',b.dataset.page!=='home');$('#settings').classList.toggle('hide',b.dataset.page!=='settings');$('#results').classList.toggle('hide',b.dataset.page==='settings')});$('#mode').value=cfg.mode;$('#url').value=cfg.url;$('#token').value=sessionStorage.getItem('api-token')||'';$('#config').onsubmit=e=>{e.preventDefault();try{let url=$('#url').value.trim().replace(/\/$/,'');if($('#mode').value==='api'&&new URL(url).protocol!=='https:')throw Error('Use uma URL HTTPS válida.');cfg={mode:$('#mode').value,url};localStorage.setItem('config-v1',JSON.stringify(cfg));sessionStorage.setItem('api-token',$('#token').value);render();toast('Configuração salva.')}catch(e){toast(e.message)}};
for(const r of records)if(r.status==='Processando'){r.status='Erro';r.message='Sessão interrompida. Tente novamente.'}persist();pump();
